question.en:
What will this code output and why?
```js
const fs = require('fs');
const stream = fs.createReadStream('large-file.txt', { highWaterMark: 16 * 1024 });
stream.on('data', (chunk) => {
  console.log('Chunk received:', chunk.length);
  stream.pause();
  setTimeout(() => stream.resume(), 100);
});
```

